# Stories for albums 401–450 (long format agreed with the owner: three paragraphs + a listening tip,
# ~220 words per story, three picks with ~12-word notes). Original Hebrew; facts checked on the web, uncertain ones softened.
# Used by tools/batches/build_401_450.py; later edits: python3 tools/apply_stories.py stories_401_450
STORIES = {}
def add(n, story, picks): STORIES[n] = {'story': story, 'picks': picks}

add(401, [
'''הג׳אם, שלישייה מווקינג שבדרום אנגליה, הגיעו עם גל הפאנק של 1977, אבל תמיד היו קצת שונים: חליפות מחויטות, אהבה למוזיקת המודס של שנות השישים ולקינקס ולמי. האלבום השני שלהם התקבל בפושרות, ופול ולר, הכותב והזמר, היה בן עשרים בלבד וחשש שנגמרו לו הרעיונות. ב־All Mod Cons, שיצא בסוף 1978, הוא הוכיח שהחשש היה מיותר.''',
'''זה רוק מהיר ונמרץ, עם גיטרה חדה, בס מקפץ של ברוס פוקסטון ותופים של ריק באקלר, אבל גם שירים שקטים ומפתיעים. ולר כותב על אנגליה של היום־יום: על איש העסקים המנומס והמרובע ב־Mr. Clean, על הכוכב שמגלה שאף אחד לא באמת היה חבר שלו ב־To Be Someone, ועל אהבה פשוטה ב־English Rose, בלדה אקוסטית עדינה. יש גם גרסה נלהבת ל־David Watts של הקינקס, שיר על ילד בית ספר שכולם מקנאים בו. בסוף מגיע Down in the Tube Station at Midnight, סיפור מצמרר על אדם שחוזר הביתה ברכבת התחתית ונתקף בידי בריונים, בזמן שאשתו מחכה לו בבית.''',
'''האלבום הפך את הג׳אם לאחת הלהקות האהובות באנגליה, ואת ולר לאחד הכותבים החשובים של דורו, מי שמתעד את החיים הבריטיים כמו ריי דייוויס לפניו. בשנים שאחר כך הלהקה הגיעה שוב ושוב למקום הראשון במצעד הסינגלים. באמריקה הם כמעט לא הצליחו, ובאנגליה הם נשארים אגדה.''',
'''את David Watts המקורי תמצאו אצל הקינקס ב־Something Else (אלבום 97). השוו את שתי הגרסאות, ואחר כך הקשיבו ל־Down in the Tube Station at Midnight כמו לסיפור קצר, מההתחלה ועד הסוף.''',
], [
('English Rose', 'בלדה אקוסטית עדינה ויפה, הפתעה שקטה באמצע אלבום נמרץ ומהיר.'),
('David Watts', 'גרסה נלהבת לשיר של הקינקס על הילד שכולם בבית הספר מקנאים בו.'),
('Down in the Tube Station at Midnight', 'סיפור קצר ומצמרר על נסיעה לילית ברכבת התחתית של לונדון.'),
])

add(402, [
'''ג׳ו איליי גדל בלאבוק, עיר שטוחה ומאובקת במערב טקסס, והתחיל את דרכו בתחילת שנות השבעים בלהקה קטנה בשם The Flatlanders, יחד עם שני חברים כותבי שירים, ג׳ימי דייל גילמור ובאץ׳ הנקוק. הלהקה כמעט לא נשמעה מחוץ לטקסס, אבל השירים שכתבו נשארו איתו. Honky Tonk Masquerade, אלבומו השני, יצא ב־1978 ונחשב לטוב שבאלבומיו.''',
'''זה קאנטרי של בארים טקסניים, אבל עם אנרגיה של רוק: גיטרת סטיל מיללת של לויד מיינס, אקורדיון שמביא טעם מקסיקני, וקצב שמתאים לריקוד. חלק מהשירים הטובים באלבום נכתבו בידי באץ׳ הנקוק: West Texas Waltz הוא ואלס שובב ומצחיק, She Never Spoke Spanish to Me הוא שיר אהבה מתוק־מר עם ניחוח של הגבול המקסיקני, ו־Boxcars הוא שיר מלנכולי על קרונות רכבת ועל חלומות שנוסעים הלאה. שיר הנושא, שאיליי כתב בעצמו, הוא בלדה על אנשים שמסתתרים מאחורי מסכות בבר של יום שבת בלילה. הקול של איליי חם ומחוספס, והלהקה שלו נשמעת כמו חבורה שמנגנת יחד כבר שנים.''',
'''האלבום לא הפך ללהיט גדול, אבל הוא נחשב לאחד השיאים של הקאנטרי הטקסני הבועט של שנות השבעים. מוזיקאי פאנק בריטים גילו אותו, והקלאש אף לקחו את איליי איתם להופעות. הוא הראה שאפשר לחבר בין מסורת קאנטרי ישנה לבין רוקנרול מהיר, בלי לוותר על אף אחד מהם.''',
'''אם אהבתם את Red Headed Stranger של ווילי נלסון (אלבום 345), כאן תשמעו טקסס אחרת, צעירה ורועשת יותר. התחילו בשיר הנושא ואחר כך עברו ל־West Texas Waltz, ונסו לא לרקוד.''',
], [
('Honky Tonk Masquerade', 'בלדה על אנשים שמסתתרים מאחורי מסכות בבר של יום שבת בלילה.'),
('West Texas Waltz', 'ואלס שובב ומצחיק של באץ׳ הנקוק, עם אקורדיון שקשה לא לרקוד אליו.'),
('Boxcars', 'שיר מלנכולי ויפה על קרונות רכבת ועל חלומות שנוסעים הלאה בלעדינו.'),
])

add(403, [
'''האדוורטס היו מהלהקות הראשונות של הפאנק הלונדוני, והופיעו כבר ב־1977 במועדון The Roxy המפורסם. את השירים כתב ושר טי. וי. סמית׳, ואת הבס ניגנה חברתו גיי אדוורט, מהנשים הראשונות שהפכו לפנים של הפאנק. הסינגל Gary Gilmore's Eyes, על אדם שמקבל השתלת עיניים מרוצח שהוצא להורג, הכניס אותם למצעד. Crossing the Red Sea with the Adverts, אלבומם הראשון, יצא בתחילת 1978.''',
'''הצליל פשוט וישיר: גיטרות מהירות, תופים דוהרים והקול הנרגש של סמית׳. אבל המילים חכמות יותר מהרגיל בפאנק. One Chord Wonders, הפותח, צוחק על הלהקה עצמה, להקה שיודעת רק אקורד אחד ומופיעה מול קהל משועמם. Bored Teenagers הוא המנון לבני נוער שאין להם מה לעשות, ו־No Time to Be 21 מתאר את הפחד להתבגר בעולם שאין בו מקום בשבילך. ו־Great British Mistake חותם את התקליט בכעס על אנגליה של אותם ימים. כמעט כל השירים קצרים, שתיים או שלוש דקות, ונגמרים לפני שמספיקים להתעייף מהם.''',
'''הלהקה התפרקה אחרי אלבום נוסף אחד, אבל התקליט הזה נחשב לאחד האלבומים הטובים של הפאנק הבריטי הראשון, לצד אלבומי הקלאש והסקס פיסטולס. סמית׳ המשיך לכתוב ולהופיע במשך עשרות שנים, וגיי אדוורט נשארה דמות אייקונית בזכות מראה חד ובס פשוט ובטוח.''',
'''שמעו אותו אחרי אלבום הבכורה של הקלאש (אלבום 376), ושימו לב למילים של סמית׳. בין כל הצעקות מסתתר כותב שנון, עצוב ומצחיק גם יחד.''',
], [
('One Chord Wonders', 'הפותח: להקה שיודעת אקורד אחד בלבד צוחקת על עצמה ועל הקהל.'),
('Bored Teenagers', 'המנון מהיר ונרגש לבני נוער משועממים שאין להם שום מקום ללכת.'),
('No Time to Be 21', 'שיר על הפחד להתבגר בעולם שנראה שאין בו מקום בשבילך.'),
])

add(404, [
'''אחרי שני אלבומים שכמעט לא נמכרו, ביג סטאר (אלבום 242) התפרקה כמעט לגמרי. ב־1974 נשארו בממפיס רק אלכס צ׳ילטון והמתופף ג׳ודי סטיבנס, והם נכנסו לאולפן עם המפיק ג׳ים דיקינסון. צ׳ילטון היה במצב רוח קודר ומבולבל, והשירים שכתב היו שבורים ומוזרים. חברות התקליטים לא ידעו מה לעשות עם ההקלטות, והן יצאו רק ב־1978, תחת השם Third או Sister Lovers, על שם שתי האחיות שצ׳ילטון וסטיבנס יצאו איתן אז.''',
'''זה אלבום שביר, יפה ולפעמים מפחיד. יש בו שירי פופ מתוקים, כמו Thank You Friends, עם מקהלה וכלי מיתר, שנשמע כמו תודה חמה אבל גם קצת לעגנית. Big Black Car הוא נסיעה איטית בלילה, ו־Kanga Roo נבנה מגיטרה, רעשים וקול חלש, כמעט כמו חלום. Holocaust הוא אחד השירים העצובים ביותר שנכתבו ברוק, בפסנתר איטי ובקול עייף. צ׳ילטון גם שר גרסה עדינה ל־Femme Fatale של הוולווט אנדרגראונד (אלבום 91). ההפקה של דיקינסון משאירה את כל הסדקים גלויים, ומוסיפה כלי מיתר וקישוטים דווקא ברגעים הכי שבורים.''',
'''בזמנו כמעט אף אחד לא שמע את האלבום, אבל עם השנים הוא הפך לאבן יסוד לרוק האלטרנטיבי. להקות רבות כיסו שירים ממנו, ורבים רואים בו את אחד האלבומים הכנים והחשופים ביותר ברוק. אין לו סדר שירים סופי, ובכל הוצאה הוא נראה קצת אחרת.''',
'''שמעו אותו בשעת לילה, בשקט. התחילו ב־Thank You Friends, ואחר כך תנו ל־Holocaust ול־Kanga Roo לשקוע לאט.''',
], [
('Thank You Friends', 'שיר פופ מתוק עם מקהלה ומיתרים, תודה חמה עם קורטוב של לעג.'),
('Kanga Roo', 'גיטרה, רעשים וקול חלש כמעט כמו חלום, מהשירים המוזרים והיפים באלבום.'),
('Holocaust', 'פסנתר איטי וקול עייף, מהשירים העצובים והחשופים ביותר שנכתבו ברוק.'),
])

add(405, [
'''הרזידנטס, מסן פרנסיסקו, הם אחת הלהקות המסתוריות בעולם: כבר עשרות שנים לא ידוע בוודאות מי חבריה. הם הופיעו בתחפושות, ובעיקר במסכות ענקיות של גלגלי עיניים, וטענו שהזהות שלהם לא חשובה, רק המוזיקה. Duck Stab/Buster & Glen, שיצא ב־1978, מאחד שני תקליטים קצרים לאלבום אחד, ונחשב לנגיש ביותר שלהם.''',
'''השירים קצרים, משונים ומצחיקים: קלידים זולים, בס מגומגם, תופים מוזרים וקולות מעוותים שנשמעים כמו דמויות מסרט מצויר מפחיד. Constantinople הוא שיר קופצני על עיר רחוקה, Hello Skinny מתאר דמות רזה ועצובה בצלילים אפלים של צעצועים, ו־Semolina נשמע כמו שיר ילדים שהשתבש. יש גם שירים על ילד ביום הולדתו, על מרימת משקולות ועל גבינה. הכול נשמע כמו מופע בובות בחדר חשוך: גם משעשע וגם קצת מאיים. הרזידנטס לא ניסו להיות יפים; הם רצו להפתיע, לבלבל ולהצחיק, ובאלבום הזה הם עושים זאת בשירים קצרים וקליטים באופן מפתיע.''',
'''הלהקה הקימה חברת תקליטים משלה, Ralph Records, ועשתה הכול בעצמה, הרבה לפני שזה היה מקובל. הרוח העצמאית והמוזרה שלה השפיעה על להקות ניסיוניות רבות, והמסכות שלהם הפכו לאחד הדימויים המוכרים ברוק הניסיוני. Duck Stab נשאר הדלת הקלה ביותר לעולם שלהם.''',
'''זה לא אלבום לכל רגע. שמעו כמה שירים בכל פעם, כמו אוסף סיפורים קצרים ומשונים. אם תאהבו אותו, תגלו שקשה להוציא את Constantinople מהראש.''',
], [
('Constantinople', 'שיר קופצני ומוזר על עיר רחוקה, שקשה מאוד להוציא אחר כך מהראש.'),
('Hello Skinny', 'דמות רזה ועצובה, בצלילים אפלים של צעצועים ומנגינה שמתגנבת מתחת לעור.'),
('Semolina', 'נשמע כמו שיר ילדים שהשתבש, מצחיק וקצת מפחיד באותה נשימה.'),
])

add(406, [
'''בתחילת 1978 הסקס פיסטולס (אלבום 393) התפרקו באמצע סיבוב הופעות באמריקה. ג׳וני רוטן חזר לשמו האמיתי, ג׳ון ליידון, והקים להקה חדשה בשם Public Image Ltd, או בקיצור PiL. איתו היו הגיטריסט קית׳ לבין, שניגן קודם לכן בגרסה מוקדמת של הקלאש, והבסיסט ג׳ה ווֹבֶּל, חבר ילדות שכמעט לא ידע לנגן כשהתחיל. First Issue, אלבומם הראשון, יצא בסוף אותה שנה.''',
'''מהשנייה הראשונה ברור שזה לא עוד תקליט פאנק. Theme, הפותח, נמשך כמעט עשר דקות: בס כבד ואיטי, גיטרה צורמת וליידון שצועק ומקונן על רצון למות. Public Image, הסינגל, מהיר וחד, וליידון יורק בו את זעמו על מי שחשבו שהם מכירים אותו מהפיסטולס. Annalisa מבוסס על סיפור אמיתי של נערה גרמנייה שמתה אחרי טקס גירוש שדים, ו־Religion מתקיף את הכנסייה במילים בוטות. הבס של ווֹבֶּל, עמוק ומושפע מדאב ורגאיי, הוא הלב של הצליל, והגיטרה של לבין נשמעת כמו מתכת שנשברת. יש גם קטע סיום ארוך ומטורף של צחוקים ורעשים, שכמעט אפשר לקרוא לו בדיחה על חשבון חברת התקליטים.''',
'''האלבום פתח את מה שנקרא אחר כך פוסט־פאנק: מוזיקה שיוצאת מהפאנק אבל מחפשת צלילים חדשים, מהדאב, מהקראוטרוק ומהרעש. Public Image הגיע לעשירייה הראשונה באנגליה, וליידון הראה שהוא יותר מסמל של מרד.''',
'''שמעו את Public Image, ואז את Theme. בהמשך, השוו לאלבום השני של הלהקה, Metal Box (אלבום 448), שבו הרעיונות האלה הולכים עוד הרבה יותר רחוק.''',
], [
('Public Image', 'הסינגל: מהיר וחד, וליידון יורק את זעמו על מי שחשבו שהם מכירים אותו.'),
('Theme', 'הפותח: כמעט עשר דקות של בס כבד, גיטרה צורמת וצעקה ארוכה.'),
('Annalisa', 'סיפור אמיתי ומטריד על נערה שמתה אחרי טקס לגירוש שדים.'),
])

add(407, [
'''הווארד דבוטו היה הזמר הראשון של הבאזקוקס (אלבום 413), אבל עזב אחרי תקליט קצר אחד כי הרגיש שהפאנק כבר נעשה צפוי. במנצ׳סטר הוא הקים להקה חדשה, מגזין, עם הגיטריסט ג׳ון מקגיוך, הבסיסט בארי אדמסון והקלידן דייב פורמולה. Real Life, אלבומם הראשון, יצא ב־1978, ונשמע כבר כמו משהו שבא אחרי הפאנק.''',
'''הצליל עשיר ומורכב יותר משל רוב להקות הפאנק: קלידים מבשרי רעות, גיטרה חדה ויצירתית של מקגיוך, בס עבה ומלודי, ומעל הכול הקול של דבוטו, קר, עוקצני ותיאטרלי. Shot by Both Sides, הסינגל, הוא שיר מהיר וחזק על אדם שנתקע בין שני מחנות ומותקף משני הצדדים; את המוזיקה שלו כתב דבוטו יחד עם פיט שלי מהבאזקוקס. Motorcade מתאר שיירת מכוניות רשמית באווירה מאיימת, ו־The Light Pours Out of Me הוא אחד השירים החזקים באלבום, בקצב דוהר ובגיטרה שצורבת. Definitive Gaze, הפותח, מתחיל בקלידים דרמטיים ונשמע כמעט כמו פתיחה של סרט, עם דבוטו שמתבונן בעולם בעיניים מפוכחות.''',
'''מגזין לא הפכו לכוכבים, אבל רבים רואים בהם את אחת הלהקות החשובות של הפוסט־פאנק. חבריה המשיכו לדרכים מרשימות: מקגיוך ניגן אחר כך עם סוזי אנד דה בנשיז (אלבום 425), ואדמסון עם ניק קייב. להקות רבות של שנות השמונים למדו מהם איך לשלב קלידים ודרמה ברוק חד.''',
'''שמעו את Shot by Both Sides ואחר כך את גרסת הבאזקוקס לאותה מנגינה, Lipstick. מעניין לשמוע איך אותו רעיון הופך לשני שירים שונים לגמרי.''',
], [
('Shot by Both Sides', 'שיר מהיר וחזק על אדם שתקוע בין שני מחנות ונפגע משני הצדדים.'),
('Motorcade', 'שיירת מכוניות רשמית באווירה מאיימת, עם קלידים ובס כבדים ודרמטיים.'),
('The Light Pours Out of Me', 'קצב דוהר, גיטרה צורבת ודבוטו במיטבו, מהשירים החזקים באלבום.'),
])

add(408, [
'''אחרי ההצלחה של Born to Run (אלבום 334), ברוס ספרינגסטין נקלע למאבק משפטי עם המנהל הקודם שלו, ובמשך כשנה לא יכול היה להקליט. כשסוף סוף חזר לאולפן, הוא כתב עשרות שירים ובחר מתוכם רק עשרה, הקשים והרציניים ביותר. Darkness on the Edge of Town יצא ב־1978, והוא אלבום בוגר ומפוכח יותר מקודמו.''',
'''במקום החלומות הגדולים על בריחה במכונית, כאן יש אנשים שנשארים: עובדי מפעלים, בנים שלא מסתדרים עם אבותיהם, זוגות שמנסים להחזיק מעמד. הצליל חשוף ומחוספס יותר, עם גיטרות חדות, פסנתר ואורגן, והקול של ספרינגסטין נשמע עייף וכועס. Badlands, הפותח, הוא המנון סוחף על עמידה מול חיים קשים, ו־The Promised Land מתחיל במפוחית ונשמע כמו תפילה של אדם שממשיך להאמין. Racing in the Street הוא שיר ארוך ועצוב על בחור שמתחרה במכוניות בלילות, בזמן שחברתו יושבת בבית ובוכה. Factory, קצר ופשוט, מתאר את אביו של ספרינגסטין הולך בכל בוקר לעבודה במפעל, ושיר הנושא סוגר את האלבום בנחישות שקטה.''',
'''האלבום הפך לאחד האהובים של ספרינגסטין על מעריציו, ורבים רואים בו את לב העבודה שלו: שירים על כבוד, על עבודה ועל תקווה שאינה תמימה. השירים הרבים שלא נכנסו אליו יצאו רק כעבור יותר משלושים שנה, ומתברר שהוא ויתר גם על להיטים בדרך.''',
'''שמעו אותו ברצף, מ־Badlands ועד שיר הנושא. אם יש לכם זמן לשיר אחד, בחרו ב־Racing in the Street, והקשיבו לפסנתר שממשיך הרבה אחרי שהמילים נגמרות.''',
], [
('Badlands', 'הפותח: המנון סוחף על עמידה עיקשת מול חיים קשים, בגיטרה ובאורגן.'),
('Racing in the Street', 'שיר ארוך ועצוב על מרוצי מכוניות בלילה, עם פסנתר שממשיך אחרי המילים.'),
('The Promised Land', 'נפתח במפוחית ונשמע כמו תפילה של אדם שממשיך להאמין, למרות הכול.'),
])

add(409, [
'''פאנקדליק, הלהקה של ג׳ורג׳ קלינטון, הייתה האחות הפרועה והרוקיסטית של פרלמנט (אלבום 360). שתי הלהקות חלקו נגנים ורעיונות, ויחד נקראו פי־פאנק. ב־1978, אחרי שנים של אלבומים ניסיוניים ולא תמיד מצליחים, פאנקדליק הוציאו את One Nation Under a Groove, האלבום המצליח ביותר שלהם.''',
'''שיר הנושא, שקלינטון כתב יחד עם חברי הלהקה, ובהם הקלידן וולטר "ג׳וני" מוריסון, הוא אחד משירי הפאנק הגדולים שנכתבו: קצב מתגלגל, בס עבה, מקהלה של קולות וקריאה לאחדות סביב הגרוב, כלומר סביב הריקוד והמוזיקה. הוא נמשך כשבע וחצי דקות ולא מאבד לרגע את הכוח. Who Says a Funk Band Can't Play Rock?! עונה בדיוק לשאלה שבשם: גיטרות רוק כבדות על קצב פאנק, ומייקל המפטון, גיטריסט צעיר, מראה שהוא יכול לנגן כמו אלוהי הרוק. יש גם שיר עם שם ארוך ומגוחך שכולו בדיחה גסה, שיר אהבה חלק, Into You, וסיום שמח וקופצני בשם Cholly. הכול נשמע כמו מסיבה גדולה, מלאה חוש הומור, שמעולם לא לוקחת את עצמה ברצינות מלאה.''',
'''שיר הנושא הגיע למקום הראשון במצעד הרית׳ם אנד בלוז האמריקאי ונשאר שם שבועות רבים, והאלבום נמכר במיליון עותקים. מאז הוא נחשב לאחד השיאים של הפאנק, והקצבים שלו נדגמו אחר כך שוב ושוב בידי אמני היפ־הופ.''',
'''השוו אותו ל־Maggot Brain (אלבום 230), האלבום הפסיכדלי והאפל של אותה להקה משבע שנים קודם. זה אותו צוות, במצב רוח שונה לגמרי. ושמעו את שיר הנושא בווליום גבוה.''',
], [
('One Nation Under a Groove', 'קריאה לאחדות סביב הריקוד: שבע וחצי דקות של פאנק שלא מאבד כוח.'),
('Who Says a Funk Band Can\'t Play Rock?!', 'גיטרות רוק כבדות על קצב פאנק, תשובה בועטת לשאלה שבשם השיר.'),
('Cholly (Funk Getting Ready to Roll!)', 'סיום שמח וקופצני, מסיבה קטנה שחותמת את האלבום בחיוך.'),
])

add(410, [
'''ת׳רובינג גריסל, רביעייה לונדונית, התחילו כקבוצת אמנות מופע שהופיעה בגלריות ועוררה שערוריות. היו בה ג׳נסיס פי־אוריג׳, קוזי פאני טוטי, כריס קרטר ופיטר כריסטופרסון. הם הקימו חברת תקליטים בשם Industrial Records, ומשמה נולד המונח "מוזיקה תעשייתית". D.o.A.: The Third and Final Report, שיצא ב־1978, הוא אלבומם השלישי.''',
'''זו לא מוזיקה במובן הרגיל. יש כאן רעשים של מכונות, סינתיסייזרים בנויים ביד, הקלטות שיחות טלפון, קולות מעוותים וקטעים מוזיקליים עדינים שצצים פתאום באמצע. Hamburger Lady, אחד הקטעים המפורסמים שלהם, מבוסס על מכתב שתיאר אישה בבית חולים לכוויות, וקולו המעוות של פי־אוריג׳ מרחף מעל צליל מזמזם ומאיים. AB/7A, לעומת זאת, הוא קטע סינתיסייזר מלודי ונעים כמעט, שמרמז על המוזיקה האלקטרונית שתבוא. Weeping הוא קטע איטי ועצוב מאוד, כמעט קינה. יש באלבום גם קטעים שכל חבר הכין לבד, וגם גרסה מואצת של שיר האהבה United, שנדחס לשניות בודדות, כמו בדיחה על ציפייה של המאזין.''',
'''ת׳רובינג גריסל היו מקור השראה לדור שלם של מוזיקאים ניסיוניים ואלקטרוניים, מלהקות תעשייתיות קשוחות ועד מוזיקת טכנו. הם הראו שאפשר להשתמש ברעש, בטכנולוגיה ובחומרים מטרידים כחומר אמנותי, ובחלק מהקטעים שלהם כבר נשמע צליל שיעצב עשורים של מוזיקה.''',
'''זה אלבום קשה, ולא לכל אחד. התחילו ב־AB/7A, העדין מכולם, ואחר כך נסו את Hamburger Lady באוזניות, רק אם אתם מוכנים לחוויה לא נוחה.''',
], [
('Hamburger Lady', 'קטע מזמזם ומאיים על אישה בבית חולים לכוויות, מהמפורסמים שלהם.'),
('AB/7A', 'קטע סינתיסייזר מלודי ונעים כמעט, שמרמז על המוזיקה האלקטרונית שתבוא.'),
('Weeping', 'קטע איטי ועצוב מאוד, כמעט קינה, ברגע שקט באלבום רועש.'),
])

add(411, [
'''ת׳ין ליזי, הלהקה האירית של פיל לינוט, הייתה בשיא כוחה באמצע שנות השבעים, והייתה ידועה בעיקר כלהקת הופעות מצוינת. Live and Dangerous, אלבום כפול שיצא ב־1978, נבנה מהקלטות של הופעות בלונדון ובטורונטו בשנים 1976–1977, בהפקת טוני ויסקונטי. עם השנים התברר שחלקים ממנו תוקנו והוקלטו מחדש באולפן, ועד היום מתווכחים כמה.''',
'''מה שבטוח הוא שהאנרגיה אמיתית. שני הגיטריסטים, סקוט גורהם ובריאן רוברטסון, מנגנים יחד מנגינות כפולות והרמוניות, הצליל שהפך לסימן ההיכר של הלהקה. לינוט, זמר ובסיסט, כתב כמעט את כל השירים, והוא מדבר עם הקהל כמו חבר ותיק. The Boys Are Back in Town, הלהיט הגדול שלהם, נשמע כאן כמו חגיגה של חברים שחוזרים לעיר. Emerald הוא שיר רוק כבד בהשראת מלחמות ואגדות אירים, Still in Love with You היא בלדה איטית עם סולו גיטרה ארוך ובוכה, ו־Dancing in the Moonlight משוחק בקלילות ובחיוך. Cowboy Song מתחיל בשקט, כמו שיר של בוקרים ליד מדורה, ומתפרץ פתאום לרוק מהיר.''',
'''האלבום נחשב בעיני רבים לאחד מאלבומי ההופעה הטובים ביותר בתולדות הרוק, והיה הצלחה גדולה באנגליה. הגיטרות הכפולות שלו השפיעו על להקות מטאל רבות שבאו אחריהם. לינוט, בן לאם אירית ולאב מגיאנה, היה אחד מכוכבי הרוק השחורים הבודדים באירופה של אותם ימים, והפך לגיבור לאומי באירלנד.''',
'''זה אלבום שכדאי לשמוע חזק, מההתחלה ועד הסוף, כמו שהייתם עומדים בקהל. הקשיבו במיוחד לסולו הארוך ב־Still in Love with You, ואיך שתי הגיטרות משלימות זו את זו.''',
], [
('The Boys Are Back in Town', 'הלהיט הגדול שלהם, בגרסה חגיגית של חבורת חברים שחוזרת הביתה לעיר.'),
('Still in Love with You', 'בלדה איטית עם סולו גיטרה ארוך ובוכה, מהרגעים היפים באלבום.'),
('Emerald', 'רוק כבד ודוהר בהשראת אגדות ומלחמות מאירלנד, עם שתי גיטרות שרבות זו בזו.'),
])

add(412, [
'''באלבום השני שלהם, טוקינג הדס (אלבום 381) התחילו לעבוד עם בריאן אינו, שהפיק אותו. הם נסעו להקליט באולפן באיי בהאמה, ויצאו עם אלבום שחם ומקפץ יותר מקודמו. More Songs About Buildings and Food יצא ב־1978, והשם שלו צוחק על עצמו: מה עוד אפשר לכתוב, אחרי כל השירים על אהבה?''',
'''דייוויד בירן ממשיך לשיר בקול לחוץ ומתוח על דברים יומיומיים, אבל עכשיו הבס של טינה וימות׳ובה והתופים של כריס פרנץ בולטים יותר, והכול נשמע קרוב יותר לפאנק ולמוזיקה שחורה. אינו מוסיף צלילים מוזרים, הדים ושכבות קטנות, בלי לכסות את הלהקה. Found a Job מספר על זוג שמפסיק לריב מול הטלוויזיה ומתחיל לכתוב תוכניות משלו, The Girls Want to Be with the Girls שובב ומהיר, ו־The Big Country, הסיום, הוא מבט מחלון מטוס על אמריקה, שבירן מתאר ביובש ואומר בסוף שהוא לא רוצה לגור שם. הלהיט הגדול היה דווקא גרסה לשיר של אל גרין, Take Me to the River, איטי, חושני ומלא בס.''',
'''Take Me to the River הפך לשיר הראשון של הלהקה שנכנס למצעד האמריקאי, והאלבום הביא אותם לקהל רחב יותר. השיתוף עם אינו רק התחיל: שני האלבומים הבאים שלהם, ובהם Fear of Music (אלבום 434), המשיכו את הדרך הזאת והלכו רחוק יותר לקצבים אפריקאיים וניסיוניים.''',
'''השוו את Take Me to the River לגרסה המקורית של אל גרין, סול רך ומלא אהבה. אחר כך שמעו את The Big Country, ונסו לדמיין את הנוף שבירן רואה מהמטוס.''',
], [
('Take Me to the River', 'גרסה איטית וחושנית לשיר של אל גרין, הלהיט הראשון של הלהקה.'),
('Found a Job', 'זוג שמפסיק לריב מול הטלוויזיה ומתחיל להמציא תוכניות משלו.'),
('The Big Country', 'מבט יבש ומצחיק מחלון מטוס על אמריקה, והחלטה לא לגור שם.'),
])

add(413, [
'''הבאזקוקס ממנצ׳סטר היו מהלהקות הראשונות של הפאנק הבריטי. אחרי שהזמר הראשון, הווארד דבוטו, עזב כדי להקים את מגזין (אלבום 407), הגיטריסט פיט שלי נעשה הזמר והכותב הראשי. Another Music in a Different Kitchen, אלבומם הראשון, יצא ב־1978 בהפקת מרטין ראשנט.''',
'''הבאזקוקס לקחו את המהירות והרעש של הפאנק ושמו בהם שירי אהבה. שלי כותב על התאהבות, על קנאה, על געגוע ועל בלבול, ושר אותם בקול גבוה ומעט עצבני. הגיטרות מזמזמות כמו מסור, והמנגינות קליטות כמו של פופ מהשישים. Fast Cars, הפותח, הוא שיר שנון נגד מכוניות מהירות, I Don't Mind מספר על אדם שמעמיד פנים שלא אכפת לו, ו־Autonomy, שכתב הגיטריסט סטיב דיגל, הוא שיר על הרצון לעצמאות, עם פזמון שחוזר שוב ושוב. יש גם רגעים ניסיוניים יותר, ובראשם שיר הסיום Moving Away from the Pulsebeat, ארוך ורועש, עם תופים שמכים כמו לב דופק. רוב השירים קצרים מאוד, ואין בהם כמעט רגע מיותר.''',
'''הבאזקוקס הראו שאפשר לכתוב שירי פופ מושלמים בתוך הפאנק, והשפיעו על להקות רבות של פופ־פאנק שבאו אחריהם בעשורים הבאים. הם גם היו מהלהקות הראשונות שהוציאו תקליט בעצמן, בלי חברה גדולה, רעיון שהפך אחר כך לחלק חשוב מהסצנה העצמאית.''',
'''שמעו את האלבום ברצף, הוא קצר מאוד. אחר כך חפשו את הסינגלים הגדולים שלהם מאותה תקופה, שלא נכנסו לאלבום, ובראשם Ever Fallen in Love.''',
], [
('Fast Cars', 'הפותח: שיר שנון, מהיר ומזמזם נגד מכוניות מהירות ומי שמעריץ אותן.'),
('I Don\'t Mind', 'אדם שמעמיד פנים שלא אכפת לו, עם מנגינה קליטה במיוחד.'),
('Autonomy', 'שיר של סטיב דיגל על הרצון לעצמאות, עם פזמון שלא נגמר.'),
])

add(414, [
'''ואן היילן, להקה מפסדינה שבקליפורניה, ניגנה במשך שנים במסיבות ובבארים באזור לוס אנג׳לס, עד שחברת תקליטים גדולה גילתה אותה. בלהקה היו האחים אדי ואלכס ואן היילן, בני למהגרים מהולנד, הבסיסט מייקל אנתוני והזמר דייוויד לי רות׳, שואומן בלתי נלאה. אלבום הבכורה שלהם יצא ב־1978, והוקלט במהירות ובעיקר בנגינה חיה.''',
'''מה שהדהים את כולם היה הגיטרה של אדי ואן היילן. Eruption, קטע סולו קצר של כמאה שניות, מדגים את הטכניקה שלו: נגינה בשתי הידיים על צוואר הגיטרה, בנקישות מהירות, שנשמעת כמו מכונה מטורפת. נגני גיטרה בכל העולם ניסו אחר כך להבין איך הוא עושה את זה. אבל האלבום הוא לא רק סולו: Runnin' with the Devil נפתח בצפירות מכוניות ובבס כבד, Ain't Talkin' 'bout Love מבוסס על ריף פשוט וקליט במיוחד, ו־Jamie's Cryin' הוא שיר פופ־רוק שמח. יש גם גרסה סוערת ל־You Really Got Me של הקינקס, ובלוז ישן, Ice Cream Man, שרות׳ פותח לבד בגיטרה אקוסטית ואחר כך הלהקה מתפוצצת. הכול נשמע כמו מסיבה רועשת וקצת פרועה.''',
'''האלבום נמכר ביותר מעשרה מיליון עותקים באמריקה, ושינה את הדרך שבה ניגנו גיטרה ברוק. אדי ואן היילן נחשב מאז לאחד הגיטריסטים המשפיעים בכל הזמנים, והלהקה פתחה את הדרך לרוק הכבד והמבריק של שנות השמונים.''',
'''שמעו את Eruption ומיד אחריו את You Really Got Me, כמו באלבום. זו הדרך שבה רוב העולם שמע לראשונה את אדי ואן היילן.''',
], [
('Eruption', 'סולו גיטרה קצר ומדהים, שבו אדי ואן היילן מנגן בשתי הידיים על צוואר הגיטרה.'),
('Runnin\' with the Devil', 'נפתח בצפירות ובבס כבד, ומתגלגל לרוק גדול עם פזמון שקל לשיר.'),
('Ain\'t Talkin\' \'bout Love', 'ריף פשוט וקליט במיוחד, מהשירים המוכרים ביותר של הלהקה.'),
])

add(415, [
'''ווילי קולון, טרומבוניסט ומנהיג להקה מניו יורק, ורובן בלאדס, זמר וכותב מפנמה, נפגשו בחברת התקליטים פאניה, הבית של מוזיקת הסלסה בניו יורק של שנות השבעים. יחד הם הוציאו ב־1978 את Siembra, שמשמעות שמו בספרדית היא "זריעה".''',
'''המוזיקה היא סלסה חמה וסוחפת: טרומבונים חזקים, פסנתר מתגלגל, כלי הקשה לטיניים ומקהלה שעונה לזמר. אבל בלאדס הביא מילים שלא היו מקובלות בסלסה: סיפורים על העיר, ביקורת חברתית וקריאה לאחדות. Plástico, הפותח, מתחיל בצלילים שנשמעים כמו דיסקו, ומתאר אנשים ריקים שחיים רק בשביל כסף ומראה חיצוני. בסופו בלאדס קורא בשמות של מדינות אמריקה הלטינית, כמו מסדר של עמים אחים. Pedro Navaja מספר על פושע ברחוב של ניו יורק ועל סוף מפתיע ואירוני, בהשראת "מקי סכינאי" של ברכט וויל. Buscando Guayaba ו־Ojos הם שירים קצביים לריקוד, ושיר הנושא מסיים בקריאה לזרוע היום את מה שנקצור מחר.''',
'''Siembra נחשב לאחד מאלבומי הסלסה הנמכרים ביותר בכל הזמנים, והפך לאלבום של כל אמריקה הלטינית, לא רק של ניו יורק. Pedro Navaja הפך לקלאסיקה שמכירים בכל מקום שמדברים בו ספרדית. בלאדס המשיך לקריירה ארוכה, למד משפטים, ואף התמודד פעם לנשיאות פנמה.''',
'''גם בלי להבין ספרדית אפשר ליהנות מהקצב. אם אפשר, חפשו תרגום של Pedro Navaja וקראו אותו בזמן ההאזנה: זה סיפור קצר עם סוף שלא מצפים לו.''',
], [
('Plástico', 'פתיחה בסגנון דיסקו, ביקורת על אנשים ריקים וקריאה לאחדות של עמי אמריקה הלטינית.'),
('Pedro Navaja', 'סיפור על פושע ברחוב בניו יורק, עם סוף מפתיע ואירוני.'),
('Siembra', 'שיר הנושא: קריאה לזרוע היום את מה שנקצור מחר, בקצב סוחף.'),
])

add(416, [
'''הקארס נולדו בבוסטון. ריק אוקאסק, כותב השירים, ובנג׳מין אור, הבסיסט והזמר השני, ניגנו יחד שנים בלהקות שונות עד שמצאו את הנוסחה. ב־1978 יצא אלבום הבכורה שלהם, בהפקת רוי תומס בייקר, שעבד קודם לכן עם קווין. הוא הפך מיד לאחד מאלבומי הבכורה המצליחים של התקופה.''',
'''הצליל הוא חיבור מבריק בין רוק פשוט של שנות החמישים והשישים לבין משהו חדש וקר יותר: קלידים מצפצפים של גרג הוקס, גיטרה קצרה וחדה של אליוט איסטון, והרמוניות קוליות שמזכירות את קווין. אוקאסק שר בקול יבש ומרוחק, ואור שר את השירים הרכים יותר. Just What I Needed, בקולו של אור, הוא שיר אהבה קליט ומבודח, My Best Friend's Girl מתחיל במחיאות כפיים ומספר על בחורה שעברה לחבר הכי טוב, ו־Good Times Roll, הפותח, איטי, מתגרה ומלא מקהלות. בצד השני של התקליט השירים נעשים מוזרים יותר: Moving in Stereo נשמע כמו חלום אלקטרוני וממשיך בלי הפסקה ל־All Mixed Up, שמסיים את האלבום בשירה גבוהה ובסקסופון.''',
'''כמעט כל שיר באלבום הפך ללהיט ברדיו, והוא נשאר במצעד האמריקאי זמן רב מאוד. הקארס הראו שאפשר לקחת רעיונות מהגל החדש ומהפאנק ולהפוך אותם לפופ־רוק שמתאים לרדיו, והשפיעו על להקות רבות של שנות השמונים.''',
'''שמעו את Moving in Stereo ו־All Mixed Up ברצף, כמו שהם מופיעים באלבום. זה החלק הכי מפתיע בתקליט, שמרמז לאן הלהקה תלך בהמשך.''',
], [
('Just What I Needed', 'שיר אהבה קליט ומבודח בקולו של בנג׳מין אור, מהלהיטים הגדולים שלהם.'),
('My Best Friend\'s Girl', 'מחיאות כפיים, גיטרה של שנות החמישים, וסיפור על בחורה שעברה לחבר.'),
('Moving in Stereo', 'קלידים וקצב קר, כמו חלום אלקטרוני, והצד המוזר והמפתיע של הלהקה.'),
])

add(417, [
'''דבו באו מאקרון שבאוהיו, עיר תעשייה אפורה, והמציאו לעצמם תיאוריה: "דה־אבולוציה", כלומר הרעיון שבני האדם לא מתקדמים אלא נסוגים לאחור, הופכים למכונות מטופשות. הם הופיעו בסרבלים תעשייתיים זהים ובמשקפי מגן, כמו פועלים בפס ייצור. Q: Are We Not Men? A: We Are Devo! יצא ב־1978, בהפקת בריאן אינו, שהוקלט בחלקו בגרמניה.''',
'''המוזיקה נשמעת כמו רוקנרול שעבר דרך מכונה: קצבים נוקשים ועצבניים, גיטרות קטועות, סינתיסייזרים מצייצים, וקולות שנשמעים כמו רובוטים מבוהלים. Jocko Homo, השיר המרכזי, הוא סוג של מניפסט, עם קריאות ומענה: "האם אנחנו לא בני אדם? אנחנו דבו!". הגרסה שלהם ל־Satisfaction של הרולינג סטונז מפורקת לגמרי: קצב שבור, מילים מגומגמות וקול היסטרי, עד שהשיר כמעט לא מזוהה. Uncontrollable Urge פותח באנרגיה מתפרצת, ו־Gut Feeling בנוי מלחן גיטרה שחוזר על עצמו ומאיץ לאט, עד שהוא נגמר בצעקות. כל השירים נשמעים כמו בדיחה, אבל בדיחה עם עוקץ על חיים של צריכה, פרסומות ועבודה משעממת.''',
'''דבו השפיעו מאוד על הגל החדש ועל המוזיקה האלקטרונית של שנות השמונים. דייוויד בואי ואיגי פופ היו מהראשונים שהתלהבו מהם, והלהקה הקדימה את זמנה גם בקליפים שלה, שכבר אז נראו כמו אמנות וידאו. לימים חבר הלהקה מארק מאת׳רסבו הפך למלחין מוכר של מוזיקה לסרטים ולתוכניות טלוויזיה.''',
'''שמעו קודם את Satisfaction המקורי של הסטונז, ואחר כך את הגרסה של דבו. אם אהבתם, עברו ל־Before and After Science של אינו (אלבום 368), שהוקלט בערך באותה תקופה.''',
], [
('Jocko Homo', 'המניפסט של הלהקה: "האם אנחנו לא בני אדם? אנחנו דבו!".'),
('(I Can\'t Get No) Satisfaction', 'שיר של הסטונז, מפורק לקצב שבור ולקול היסטרי עד שכמעט לא מזהים אותו.'),
('Gut Feeling', 'לחן גיטרה שחוזר על עצמו ומאיץ לאט, עד שהכול מתפרץ בצעקות.'),
])

add(418, [
'''מארק נופפלר עבד כעיתונאי וכמרצה לפני שהקים בלונדון את דייר סטרייטס, עם אחיו דייוויד, הבסיסט ג׳ון איליסלי והמתופף פיק ווית׳רס. הם הקליטו כמה שירים בזול, ואחד מהם, Sultans of Swing, הגיע לתוכנית רדיו של הבי בי סי. תוך זמן קצר קיבלו חוזה, ואלבום הבכורה שלהם יצא ב־1978. השם, "מצוקה נואשת", צחק על מצבם הכלכלי של החברים.''',
'''בזמן שהפאנק שלט בלונדון, דייר סטרייטס ניגנו משהו שקט ומדויק: רוק רגוע, מושפע מבלוז, מקאנטרי ומבוב דילן. נופפלר מנגן בגיטרה חשמלית באצבעות, בלי מפרט, וזה נותן לנגינה שלו צליל נקי, מתגלגל ומדבר. הוא שר בקול נמוך, כמעט מספר סיפורים. Sultans of Swing מתאר להקת ג׳אז קטנה שמנגנת בפאב ריק למחצה בלילה גשום, ומסתיים בסולו גיטרה מבריק. Down to the Waterline, הפותח, מתאר זיכרונות של אהבה ליד הנמל, Wild West End הוא שיר מתוק ומהורהר על שיטוט ברחובות לונדון, ו־Water of Love משתמש בגיטרה מתכתית וקצב עצל שמזכירים מוזיקה של הדרום האמריקאי.''',
'''Sultans of Swing הפך ללהיט בכל העולם, והאלבום הביא ללהקה הצלחה מיידית. דייר סטרייטס הפכו אחר כך לאחת הלהקות הגדולות של שנות השמונים, ונופפלר לאחד מנגני הגיטרה המוערכים בעולם, גם כמלחין של פסקולים לסרטים.''',
'''הקשיבו לסולו בסוף Sultans of Swing בתשומת לב, ושימו לב שהוא מנוגן באצבעות. אחר כך שמעו את Wild West End, השקט והיפה באלבום.''',
], [
('Sultans of Swing', 'להקת ג׳אז קטנה בפאב ריק בלילה גשום, וסולו גיטרה מבריק בסוף.'),
('Down to the Waterline', 'הפותח: זיכרונות של אהבה ליד הנמל, בגיטרה צלולה ומתגלגלת.'),
('Wild West End', 'שיר מתוק ומהורהר על שיטוט בלילה ברחובות לונדון.'),
])

add(419, [
'''הסיינטס באו מבריסביין שבאוסטרליה, רחוק מאוד מניו יורק ומלונדון, ובכל זאת הוציאו ב־1976 את (I'm) Stranded, אחד מסינגלי הפאנק הראשונים בעולם. הזמר כריס ביילי והגיטריסט אד קופר עברו אחר כך ללונדון, אבל לא התחברו לסצנה שם. Eternally Yours, אלבומם השני, יצא ב־1978, והוא מראה להקה שכבר רוצה לצאת מגבולות הפאנק.''',
'''הבסיס עדיין מהיר ורועש: גיטרה עבה וזועמת של קופר, תופים דוהרים והקול המחוספס והעמוק של ביילי. אבל עכשיו נכנסים גם כלי נשיפה, מנגינות של סול ושירים איטיים יותר. Know Your Product, הפותח, הוא שיר נגד פרסומות וצרכנות, עם חצוצרות וסקסופונים שנשמעים כמו להקת סול שהשתגעה. This Perfect Day, שיצא כסינגל באנגליה, הוא פאנק ישיר וחזק, ו־Orstralia, בשם שמחקה את המבטא המקומי, הוא מבט עוקצני על המולדת. גם בשירים האיטיים יותר מתגלה שביילי היה זמר רגיש יותר ממה שנדמה בשירים הרועשים. הלהקה לא ניסתה לחקות את הפאנק הבריטי, והיא נשמעת קרובה דווקא לרוק הקשוח של שנות השישים.''',
'''הסיינטס לא הפכו לכוכבים, אבל נחשבים לאחת הלהקות החשובות ברוק האוסטרלי, והשפיעו על להקות רבות מאוסטרליה ומחוצה לה. קופר עזב זמן קצר אחרי האלבום השלישי והקים להקות משלו, וביילי המשיך עם הסיינטס במשך עשרות שנים.''',
'''שמעו את Know Your Product בקול רם, והשוו אותו לשירי הקלאש מאותה תקופה (אלבום 376). זו אותה תחושת זעם, אבל עם חצוצרות שמוסיפות לה שמחה פרועה.''',
], [
('Know Your Product', 'הפותח: שיר זועם נגד פרסומות, עם כלי נשיפה שנשמעים כמו להקת סול שהשתגעה.'),
('This Perfect Day', 'פאנק ישיר וחזק, שיצא כסינגל באנגליה והפך לאחד השירים המוכרים שלהם.'),
('Orstralia', 'מבט עוקצני על המולדת, בשם שמחקה את המבטא האוסטרלי.'),
])

add(420, [
'''באמצע שנות השבעים מרווין גיי (אלבומים 207 ו־280) התגרש מאשתו הראשונה, אנה גורדי, אחותו של מייסד מוטאון. במסגרת הסכם הגירושים נקבע שחלק מהכסף שיקבל על האלבום הבא שלו יעבור אליה. גיי החליט בהתחלה להקליט משהו מהיר ולא מושקע, אבל בסוף עשה את ההפך: אלבום כפול ואישי מאוד, שכולו על הנישואים ועל הפירוק שלהם. Here, My Dear יצא בסוף 1978.''',
'''זה אלבום של סול איטי ומהורהר, עם קצבים רכים, קלידים חמים, שכבות של קולות של גיי עצמו ונגינה חופשית וארוכה. הוא לא מחפש להיטים, אלא מספר סיפור: I Met a Little Girl נזכר באהבה הראשונה ובחלומות, When Did You Stop Loving Me, When Did I Stop Loving You שואל בכאב מתי זה נגמר, ו־Anger מתאר את הכעס שאוכל את שני הצדדים. יש גם רגעים מפתיעים, כמו A Funky Space Reincarnation, שיר פאנק שובב על אהבה בעתיד בחלל, ו־Anna's Song, שהוא פנייה ישירה לאישה שאהב. לאורך האלבום גיי כועס, מתגעגע, מאשים ומתחרט, לפעמים באותו שיר.''',
'''בזמנו האלבום נכשל, והמבקרים ראו בו התבכיינות ארוכה. עם השנים הוא זכה להערכה מחודשת, ורבים רואים בו אחד מאלבומי הפרידה הכנים ביותר שנכתבו, יומן אישי כמעט בלי מסננים. הוא מזכיר שגם אלבום שנולד מתוך חובה יכול להפוך ליצירה אמיתית.''',
'''זה אלבום ארוך, ולא קל. שמעו אותו בערב שקט, בכמה חלקים אם צריך, והתחילו ב־When Did You Stop Loving Me, When Did I Stop Loving You, שהוא הלב של הסיפור.''',
], [
('When Did You Stop Loving Me, When Did I Stop Loving You', 'הלב של האלבום: שאלה כואבת ומהורהרת על הרגע שבו האהבה נגמרה.'),
('Anna\'s Song', 'פנייה ישירה ורכה לאישה שאהב, בין געגוע לחרטה.'),
('A Funky Space Reincarnation', 'רגע שובב ומפתיע: שיר פאנק על אהבה בעתיד, בחלל.'),
])

add(421, [
'''ב־1978 ווילי נלסון היה כבר כוכב קאנטרי גדול, בזכות אלבומים כמו Red Headed Stranger (אלבום 345). אז הוא עשה משהו שחברת התקליטים חששה ממנו מאוד: אלבום שלם של שירים ישנים מהעשורים שלפני הרוקנרול, שירים שגדל עליהם ברדיו, מגרשווין ועד הוגי קרמייקל. את ההפקה הוא הפקיד בידי בוקר טי. ג׳ונס, מוזיקאי סול מממפיס שגר אז בשכנות אליו.''',
'''Stardust נשמע פשוט ורגוע מאוד: הגיטרה האקוסטית הבלויה של נלסון, מפוחית עדינה, פסנתר, אורגן של בוקר טי ומעט כלי מיתר. הקול של נלסון, דק וחם, שר את השירים המוכרים כאילו הם שלו, בקצב חופשי משלו, תמיד קצת לפני או אחרי הלהקה. שיר הנושא, של הוגי קרמייקל, נשמע כמו חלום ישן, Georgia on My Mind עצוב ומתגעגע, ו־Blue Skies שמח ושלו. יש גם September Song, על הזמן שעובר, ו־Moonlight in Vermont השקט. אין כאן עיבודים גדולים או מקהלות, רק חבורה קטנה שמנגנת בנחת ומניחה לשירים לדבר בעד עצמם.''',
'''החשש של חברת התקליטים התברר כמיותר: האלבום נמכר במיליונים, ונשאר במצעד אלבומי הקאנטרי האמריקאי כמעט עשר שנים. הוא הראה שכוכבי קאנטרי ורוק יכולים לשיר את השירים הישנים של אמריקה בלי להישמע מיושנים, ואמנים רבים הלכו אחר כך בעקבותיו.''',
'''זה אלבום מושלם לערב שקט או לנסיעה ארוכה. שמעו את שיר הנושא, ואחר כך את Georgia on My Mind, והשוו לגרסה המפורסמת של ריי צ׳ארלס.''',
], [
('Stardust', 'שיר הנושא, של הוגי קרמייקל, בגרסה שקטה ורכה שנשמעת כמו חלום ישן.'),
('Georgia on My Mind', 'עצוב ומתגעגע, עם מפוחית עדינה וקול דק וחם.'),
('Blue Skies', 'שיר ישן, שמח ושלו, שנלסון שר בנחת ובחיוך.'),
])

add(422, [
'''שיק, מניו יורק, נבנתה סביב שני מוזיקאים: הגיטריסט נייל רוג׳רס והבסיסט ברנרד אדוארדס, שכתבו והפיקו יחד את כל השירים. איתם ניגן המתופף טוני תומפסון, ושתי זמרות, אלפה אנדרסון ולוסי מרטין, שרו בחזית. C'est Chic, אלבומם השני, יצא ב־1978, בשיא ימי הדיסקו.''',
'''הסוד של שיק הוא הדיוק. הגיטרה של רוג׳רס מנגנת אקורדים קצרים ומתקתקים, כמו שעון, והבס של אדוארדס מתגלגל ורוקד מתחתם. מעל זה יש כלי מיתר, קולות נקיים ומסונכרנים, ותופים יציבים שקשה לא לזוז אליהם. Le Freak נולד בערב אחד שבו רוג׳רס ואדוארדס לא הורשו להיכנס למועדון סטודיו 54; הם חזרו הביתה כועסים וכתבו על זה שיר, שהפך לאחד מלהיטי הדיסקו הגדולים. I Want Your Love הוא שיר איטי וחושני, עם פעמונים וקולות מלאי תשוקה, ו־At Last I Am Free הוא בלדה שקטה ועצובה מאוד, שמראה צד אחר של הלהקה. יש גם קטעים אינסטרומנטליים, כמו Savoir Faire, שבהם הגיטרה של רוג׳רס שרה בלי מילים.''',
'''Le Freak הגיע למקום הראשון במצעד האמריקאי והיה במשך שנים אחד הסינגלים הנמכרים ביותר של חברת התקליטים שלו. רוג׳רס ואדוארדס הפכו לאחר מכן למפיקים מבוקשים, והצליל שלהם, במיוחד הגיטרה והבס, השפיע על פופ, פאנק והיפ־הופ עד היום.''',
'''שמעו את Le Freak באוזניות, והקשיבו רק לבס של אדוארדס. אחר כך השוו ל־Risqué (אלבום 436), האלבום הבא שלהם.''',
], [
('Le Freak', 'להיט דיסקו ענק שנולד מכעס, אחרי שלא הורשו להיכנס למועדון.'),
('I Want Your Love', 'שיר איטי וחושני עם פעמונים וקולות מלאי תשוקה.'),
('At Last I Am Free', 'בלדה שקטה ועצובה מאוד, צד אחר ומפתיע של הלהקה.'),
])

add(423, [
'''פולי סטיירין, נערה לונדונית בת תשע עשרה, אמא אנגלייה ואבא סומלי, ראתה הופעה של הסקס פיסטולס (אלבום 393) והחליטה להקים להקה משלה. כך נולדו אקס־ריי ספקס, עם סקסופון בחזית במקום גיטרה סולו, ועם זמרת שלבשה צבעים זוהרים, גשר על השיניים, וצעקה בקול חזק וחד כתער. Germfree Adolescents, אלבומם היחיד בשנות השבעים, יצא ב־1978.''',
'''המוזיקה היא פאנק מהיר ושמח, עם סקסופון צווחני שרץ לצד הגיטרה ונותן לכל שיר טעם של מסיבה פרועה. אבל המילים של סטיירין חכמות ומצחיקות, ועוסקות בנושא שמעט להקות פאנק נגעו בו: עולם של פלסטיק, פרסומות, צרכנות וזהות מבולבלת. The Day the World Turned Day-Glo מתאר עולם שבו הכול הופך לפלסטיק זוהר ומלאכותי, Identity שואל מי אנחנו באמת כשאנחנו מחקים תמונות מהטלוויזיה, ו־Art-I-Ficial מספר על נערה שמרגישה שהיא נבנתה לפי הפרסומות. שיר הנושא איטי יותר, כמעט בלדה, על בני נוער שמנקים את עצמם עד שלא נשאר מהם כלום. הכול נשמע שובב, אבל מאחורי הצחוק יש ביקורת חדה.''',
'''הלהקה לא החזיקה מעמד זמן רב, אבל האלבום נחשב לאחד השיאים של הפאנק הבריטי, ופולי סטיירין הפכה לדמות אהובה ומשפיעה, במיוחד על נשים במוזיקה. הרעיונות שלה על צרכנות ועל זהות נשמעים היום עדכניים יותר מאי פעם.''',
'''שמעו את The Day the World Turned Day-Glo ושימו לב לסקסופון. זה הצליל שמבדיל את הלהקה מכל שאר להקות הפאנק של אותה שנה.''',
], [
('The Day the World Turned Day-Glo', 'עולם שבו הכול הופך לפלסטיק זוהר ומלאכותי, עם סקסופון פרוע.'),
('Identity', 'שאלה חדה על זהות: מי אנחנו כשאנחנו מחקים תמונות מהטלוויזיה?'),
('Germfree Adolescents', 'שיר הנושא, איטי כמעט כמו בלדה, על נוער שמנקה את עצמו עד שלא נשאר כלום.'),
])

add(424, [
'''בריאן אינו (אלבומים 300, 326 ו־368) חיפש כבר כמה שנים מוזיקה מסוג אחר: מוזיקה שלא דורשת תשומת לב, אלא יוצרת אווירה בחדר, כמו אור או צבע. יום אחד, כשישב בנמל תעופה בגרמניה, הוא חשב על השאלה איזו מוזיקה הייתה מתאימה למקום כזה, שבו אנשים ממתינים, לחוצים ולפעמים מפחדים לטוס. התשובה היא Ambient 1: Music for Airports, שיצא ב־1978 ונתן שם לסגנון שלם: אמביינט.''',
'''באלבום ארבעה קטעים ארוכים, בלי שמות, רק מספרים. הם נבנו מלולאות של סרט הקלטה באורכים שונים, שחוזרות על עצמן ונפגשות כל פעם בצירוף אחר, כך שהמוזיקה משתנה לאט כמעט בלי שמרגישים. 1/1 פותח בכמה תווים שקטים של פסנתר, שנוגנו בחלקם בידי רוברט וייאט, שחוזרים שוב ושוב בהפסקות ארוכות. 2/1 בנוי מקולות נשיים בלי מילים, שנשמעים כמו מקהלה רחוקה, ו־1/2 מחבר בין הקולות לפסנתר. 2/2 נשען על צלילי סינתיסייזר רכים ונמוכים. אין באלבום קצב, אין פזמונים, ואין רגע שבו משהו קורה פתאום. אינו כתב שהמוזיקה צריכה להיות מעניינת למי שמקשיב, וקלה להתעלמות למי שלא.''',
'''הרעיון נשמע אז מוזר, אבל הוא שינה את המוזיקה. מוזיקת אמביינט, מוזיקת רגיעה ומוזיקה אלקטרונית שקטה רבה נולדו מהאלבום הזה, ועד היום מוזיקאים ואמנים חוזרים אליו. הוא אפילו הושמע בכמה נמלי תעופה.''',
'''אל תקשיבו לו בריכוז. שימו אותו בשקט ברקע, בזמן קריאה, עבודה או לפני השינה, ותנו לו למלא את החדר.''',
], [
('1/1', 'כמה תווי פסנתר שקטים שחוזרים שוב ושוב, בהפסקות ארוכות ומרגיעות.'),
('2/1', 'קולות נשיים בלי מילים, שנשמעים כמו מקהלה רחוקה ורכה.'),
('1/2', 'הקולות והפסנתר נפגשים, והכול משתנה לאט כמעט בלי שמרגישים.'),
])

add(425, [
'''סוזי סו וסטיבן סברין היו חלק מחבורה של מעריצים צעירים שנסעו אחרי הסקס פיסטולס (אלבום 393) לכל הופעה. ב־1976 הם עלו לבמה לראשונה, בלי לדעת לנגן כמעט, והתחילו את סוזי אנד דה בנשיז. שנתיים אחר כך, עם הגיטריסט ג׳ון מקיי והמתופף קני מוריס, הם הוציאו את The Scream, אלבומם הראשון.''',
'''מההתחלה הם נשמעו שונה משאר להקות הפאנק: פחות מהירים, יותר קרים, אפלים ומוזרים. הגיטרה של מקיי לא מנגנת אקורדים רגילים, אלא צלילים חדים, צורמים ומתכתיים, והתופים של מוריס נשמעים כמו טקס שבטי. מעל כל זה סוזי שרה בקול חזק ומלכותי, קצת מאיים. Jigsaw Feeling מתאר תחושה של אדם שמתפרק לחלקים, Metal Postcard הוא שיר קר ומתכתי בהשראת אמנות שנוצרה נגד הנאצים, עם שם משנה בגרמנית, ו־Switch, הסיום הארוך, עובר בין כמה חלקים ומצבי רוח. יש גם גרסה אפלה ושבורה ל־Helter Skelter של הביטלס, שנשמעת כאן כמו סיוט. Suburban Relapse מתאר עקרת בית שמאבדת את שפיותה בפרבר, שיר מפחיד ומצחיק גם יחד.''',
'''The Scream נחשב לאחד האלבומים הראשונים של הפוסט־פאנק, והשפיע רבות על מה שנקרא אחר כך "גותי": מוזיקה אפלה, דרמטית ורומנטית. סוזי עצמה הפכה לאייקון של סגנון, והלהקה המשיכה עוד שנים רבות, עם הרכבים מתחלפים ועם להיטים באנגליה.''',
'''שמעו את Jigsaw Feeling ושימו לב לגיטרה של מקיי: כמעט אין בה אקורדים, רק צלילים חדים. אחר כך שמעו את Real Life של מגזין (אלבום 407) מאותה שנה.''',
], [
('Jigsaw Feeling', 'תחושה של אדם שמתפרק לחלקים, עם גיטרה חדה ותופים כמו טקס.'),
('Metal Postcard (Mittageisen)', 'שיר קר ומתכתי בהשראת אמנות נגד הנאצים, עם שם משנה בגרמנית.'),
('Switch', 'הסיום הארוך, שעובר בין חלקים ומצבי רוח שונים ומראה את כל יכולות הלהקה.'),
])

add(426, [
'''AC/DC, הלהקה האוסטרלית של האחים אנגוס ומלקולם יאנג, הופיעה בלי הפסקה במשך שנים, אבל עדיין לא כבשה את אמריקה. ב־1979 חברת התקליטים החליטה להחליף את המפיקים הוותיקים שלהם ולהביא את רוברט ג׳ון "מאט" לאנג, מפיק צעיר שידע ללטש צליל בלי לאבד את הכוח שלו. Highway to Hell, שיצא באותה שנה, היה האלבום האחרון עם הזמר בון סקוט, שמת בתחילת 1980.''',
'''הנוסחה פשוטה, והיא עובדת: ריפים של גיטרה, חזקים ופשוטים, קצב יציב כמו פטיש, ובון סקוט שצועק ושר בחיוך ממזרי. אנגוס יאנג, בתלבושת תלמיד בית ספר, מנגן סולואים מהירים ופרועים, ומלקולם מחזיק את הכול בגיטרת קצב עקשנית. בהשוואה לאלבומים הקודמים, הצליל כאן נקי ומלוטש יותר, והפזמונים גדולים ונשמעים כמו מקהלת אצטדיון. שיר הנושא, שמתחיל בריף קצר ומפורסם, מתאר את החיים בדרכים, מהופעה להופעה, בלי מנוחה. Touch Too Much הוא שיר קליט במיוחד, If You Want Blood (You've Got It) הוא המנון של להקת הופעות, ו־Girls Got Rhythm הוא רוקנרול מהיר ושמח.''',
'''Highway to Hell היה האלבום הראשון של הלהקה שהצליח בגדול באמריקה, ופתח לה את הדרך להפוך לאחת מלהקות הרוק הגדולות בעולם. אחרי מותו של סקוט, הלהקה המשיכה עם זמר חדש, ובאלבום הבא, Back in Black, הגיעה להצלחה עוד גדולה יותר.''',
'''שמעו את שיר הנושא בווליום גבוה, ושימו לב כמה מעט צלילים יש בריף. אחר כך שמעו את Touch Too Much, ותנו לפזמון להיכנס לראש.''',
], [
('Highway to Hell', 'ריף קצר ומפורסם ושיר על החיים בדרכים, מהופעה להופעה, בלי מנוחה.'),
('Touch Too Much', 'שיר קליט במיוחד עם פזמון גדול, שמראה את ההפקה החדשה של מאט לאנג.'),
('If You Want Blood (You\'ve Got It)', 'המנון מהיר ובועט של להקה שחיה על הבמה.'),
])

add(427, [
'''סיסטר סלדג׳ היו ארבע אחיות מפילדלפיה, דבי, ג׳וני, קים וקתי, ששרו יחד מילדות. אחרי שנים של הצלחה צנועה, חברת התקליטים שלהן שלחה אותן לנייל רוג׳רס וברנרד אדוארדס, שני המוחות מאחורי שיק (אלבום 422). השניים כתבו והפיקו את כל האלבום, ובנו את השירים סביב האחיות עצמן. We Are Family יצא בתחילת 1979.''',
'''הצליל הוא הצליל של שיק במיטבו: גיטרה מתקתקת, בס רוקד, מיתרים זוהרים ותופים יציבים. אבל כאן הם מלווים ארבעה קולות חמים של אחיות, שנשמעים כמו שיחה בבית. He's the Greatest Dancer מתאר בחור מהמם במועדון ריקודים, עם שורה שמונה בגאווה שמות של מעצבי אופנה. Lost in Music הוא שיר על אנשים שהמוזיקה היא כל חייהם, שמחה והתמכרות גם יחד. שיר הנושא, בקולה של קתי, הוא הצהרה שמחה על אחדות משפחתית, עם פזמון שכל הקהל יכול לשיר. רוג׳רס ואדוארדס כתבו אותו, כך מספרים, אחרי שפגשו את האחיות והתרשמו מהקשר ביניהן. יש גם שירים רגועים יותר, כמו Thinking of You, שמראים את היכולת הקולית של האחיות.''',
'''We Are Family הפך להמנון עולמי, של משפחות, של קבוצות ספורט ושל קהילות שרצו להגיד "אנחנו ביחד". האלבום הוא אחד משיאי הדיסקו, ו־Lost in Music ו־He's the Greatest Dancer נדגמו והוקלטו מחדש שוב ושוב.''',
'''שמעו אותו אחרי C'est Chic (אלבום 422), ונסו לזהות את הגיטרה והבס של רוג׳רס ואדוארדס. מדובר באותם נגנים, רק בתפקיד המלווים.''',
], [
('We Are Family', 'הצהרה שמחה על אחדות משפחתית, עם פזמון שכל הקהל יכול לשיר.'),
('He\'s the Greatest Dancer', 'בחור מהמם במועדון, ורשימת מעצבי אופנה בגאווה, על קצב רוקד.'),
('Lost in Music', 'אנשים שהמוזיקה היא כל חייהם: שמחה והתמכרות באותה נשימה.'),
])

add(428, [
'''הקרוסיידרס התחילו כלהקת ג׳אז מיוסטון שבטקסס, עוד בשנות החמישים, ובשנות השישים נקראה הג׳אז קרוסיידרס. עם השנים הם הורידו את המילה "ג׳אז" מהשם, והתקרבו לפאנק, לסול ולמוזיקה שאפשר לרקוד אליה. ב־1979, עם הקלידן ג׳ו סמפל, הסקסופוניסט ווילטון פלדר והמתופף סטיקס הופר, הם הוציאו את Street Life, האלבום המצליח ביותר שלהם.''',
'''שיר הנושא הוא הלב של האלבום: יותר מעשר דקות של גרוב חלק ומתגלגל, עם פסנתר חשמלי, כלי מיתר וכלי נשיפה. את השיר שרה הזמרת רנדי קרופורד, שהייתה אז כמעט לא מוכרת, בקול חם וחזק, על החיים ברחוב: האורות, הריקודים והבדידות שבאה אחריהם. אחרי השיר מגיעים קטעים אינסטרומנטליים, שבהם הנגנים מדברים ביניהם כמו בהופעה: Rodeo Drive, על רחוב הקניות היוקרתי בלוס אנג׳לס, קופצני ושמח, ו־Night Faces מסיים בשקט, עם סקסופון רך ופסנתר. הכול נשמע מלוטש, רגוע ומדויק, מוזיקה של מוזיקאים ותיקים שיודעים בדיוק מה הם עושים.''',
'''Street Life הפך ללהיט גדול באמריקה ובאנגליה, והביא לרנדי קרופורד קריירה בינלאומית. האלבום נחשב לאחד השיאים של הג׳אז־פאנק ושל מה שנקרא אחר כך "ג׳אז חלק", ושיר הנושא הופיע שנים רבות אחר כך בסרט "ג׳קי בראון" של קוונטין טרנטינו.''',
'''שמעו את שיר הנושא בערב, בזמן נסיעה בעיר, וחכו לרגע שבו קרופורד נכנסת לפזמון. אחר כך שמעו את Night Faces לסיום שקט.''',
], [
('Street Life', 'יותר מעשר דקות של גרוב, עם הקול החם של רנדי קרופורד על החיים ברחוב.'),
('Rodeo Drive (High Steppin\')', 'קטע קופצני ושמח על רחוב הקניות היוקרתי של לוס אנג׳לס.'),
('Night Faces', 'סיום שקט ורגוע, עם סקסופון רך ופסנתר חשמלי.'),
])

add(429, [
'''הג׳רמס היו מהלהקות הראשונות של הפאנק בלוס אנג׳לס. הם התחילו כמעט כבדיחה, כמה בני נוער שלא ידעו לנגן, בראשות הזמר דרבי קראש, בחור חכם, ביישן ופרוע. לצידו ניגנו הגיטריסט פט סמיר, הבסיסטית לורנה דום והמתופף דון בולס. (GI), אלבומם היחיד, יצא ב־1979 בהפקת ג׳ואן ג׳ט, שהייתה אז כוכבת רוק צעירה בעצמה.''',
'''הצליל מהיר, גס ורועש: גיטרה מזמזמת, תופים מהירים מאוד, וקראש שצועק ושר מילים מסובכות ושנונות, מלאות מחשבות על כוח, שליטה וזהות. אפשר לשמוע כאן את הבסיס של מה שיקרא אחר כך "הארדקור", פאנק מהיר עוד יותר. What We Do Is Secret, הפותח, קצר ומיידי, Lexicon Devil הוא אחד השירים המוכרים שלהם, עם ריף שקשה לשכוח, ו־Richie Dagger's Crime מספר על נער מרדן בשם ריצ׳י דאגר. בסוף האלבום קטע ארוך ורועש שנמשך כמעט עשר דקות. מאחורי הרעש יש כותב מוכשר, שקרא ספרים רבים והתעניין בפילוסופיה ובדמויות של מנהיגים.''',
'''דרבי קראש מת צעיר מאוד, בסוף 1980, והלהקה נגמרה איתו. אבל האלבום השפיע מאוד על הפאנק האמריקאי, ופט סמיר המשיך לנגן, בין השאר, עם נירוונה ועם פו פייטרס. רבים רואים ב־(GI) את אחד האלבומים החשובים של הפאנק בחוף המערבי.''',
'''זה אלבום רועש וקשה, אז שמעו אותו בחלקים. התחילו ב־Lexicon Devil, ואחר כך נסו לעקוב אחרי המילים של קראש: הן חכמות יותר ממה שנדמה.''',
], [
('Lexicon Devil', 'אחד השירים המוכרים שלהם, עם ריף מהיר שקשה לשכוח.'),
('What We Do Is Secret', 'הפותח: קצר, מהיר ומיידי, פחות משתי דקות של אנרגיה.'),
('Richie Dagger\'s Crime', 'שיר מהיר ורועש, מהמוכרים שלהם, על נער מרדן בשם ריצ׳י דאגר.'),
])

add(430, [
'''הבי־52ס נולדו באתנס שבג׳ורג׳יה, עיר סטודנטים קטנה בדרום ארצות הברית, אחרי ערב שבו חמישה חברים שתו יחד וניגנו בכלים שמצאו. שמם לקוח מכינוי לתסרוקת הגבוהה של שנות השישים, שזמרות הלהקה, קייט פירסון וסינדי וילסון, אהבו לחבוש. עם פרד שניידר, שדיבר ושר כמו מנחה של מסיבה, הגיטריסט ריקי וילסון, אחיה של סינדי, והמתופף קית׳ סטריקלנד, הם הוציאו את אלבום הבכורה שלהם ב־1979.''',
'''זו מסיבה: רוק מהיר, גיטרה מוזרה ומשעשעת, אורגן צעצוע, והרבה צעקות, ציוצים וצחוקים. ריקי וילסון ניגן בגיטרה בכיוונונים מוזרים, לפעמים עם פחות מיתרים, מה שנתן לה צליל של גלי חוף וסרטי מדע בדיוני. Rock Lobster, השיר המפורסם, הוא שבע דקות של מסיבת חוף הזויה, עם קולות של יצורי ים שהזמרות מחקות. Planet Claire, הפותח, נשמע כמו פסקול של סרט חלל ישן, עם מנגינה שמזכירה את נושא "פיטר גאן". Dance This Mess Around הוא שיר ריקוד שבו סינדי וילסון צועקת בכל הכוח. יש גם גרסה מפתיעה ל־Downtown של פטולה קלארק. הכול צבעוני, מצחיק ומלא אהבה לתרבות פופ ישנה.''',
'''הבי־52ס הראו שהגל החדש יכול להיות שמח ומשוחרר, והשפיעו על להקות רבות מהסצנה של אתנס ומחוצה לה. מספרים שג׳ון לנון, ששמע את Rock Lobster, התלהב ממנו וחזר בעקבותיו לכתוב מוזיקה.''',
'''שמעו את Rock Lobster ורקדו, אין דרך אחרת. אחר כך שמעו את Planet Claire, ונסו לנחש מאיזה סרט חלל ישן הוא יצא.''',
], [
('Rock Lobster', 'שבע דקות של מסיבת חוף הזויה, עם קולות של יצורי ים.'),
('Planet Claire', 'הפותח: נשמע כמו פסקול של סרט חלל ישן ומצחיק.'),
('Dance This Mess Around', 'שיר ריקוד פרוע, שבו סינדי וילסון צועקת בכל הכוח.'),
])

add(431, [
'''הולגר צ׳וקאי היה הבסיסט של הלהקה הגרמנית קאן (אלבומים 219 ו־277), אבל גם תלמיד של המלחין קרלהיינץ שטוקהאוזן, וחובב גדול של רדיו, של סרטי הקלטה ושל גזירה והדבקה. אחרי שעזב את קאן, הוא הקליט בעצמו את Movies, שיצא ב־1979, ונעזר בכמה מחבריו לשעבר ללהקה.''',
'''המוזיקה בנויה כמו סרט: צ׳וקאי הקליט נגינה של עצמו ושל חבריו, ואז שילב בה קטעים שהקליט מהרדיו, מדיבורים ומזמרים מכל העולם, ובנה מכל זה פסיפס של צלילים. הכול נשמע טבעי ושמח, כאילו הרדיו עצמו מנגן עם הלהקה. Cool in the Pool, הפותח, הוא שיר פאנק קופצני ומבודח, שבו צ׳וקאי שר בקול חצי מדבר על קריר בבריכה. Oh Lord Give Us More Money הוא קטע ארוך ורחב, עם תפילה מבודחת לעוד כסף, ו־Persian Love, הקטע המפורסם באלבום, בנוי סביב שירה של זמר איראני שצ׳וקאי הקליט מגלי הרדיו, על גבי גיטרה רכה וקצב עדין. Hollywood Symphony, הקטע האחרון, הוא מסע ארוך בין צלילים וקולות, כמו פסקול לסרט שלא צולם.''',
'''Movies נחשב לאחד האלבומים הראשונים שבנו מוזיקה מהקלטות של אחרים, הרבה לפני שהדגימה הפכה לחלק קבוע מהמוזיקה. צ׳וקאי השפיע על מוזיקאים ניסיוניים ואלקטרוניים רבים, ושיתף פעולה אחר כך עם אמנים כמו דייוויד סילביאן מג׳פאן.''',
'''שמעו את Persian Love, ואחר כך קראו על My Life in the Bush of Ghosts של אינו ודייוויד בירן, שיצא שנתיים אחר כך ועשה דבר דומה.''',
], [
('Cool in the Pool', 'הפותח: פאנק קופצני ומבודח, שבו צ׳וקאי שר חצי מדבר על קריר בבריכה.'),
('Persian Love', 'שירה של זמר איראני שהוקלטה מהרדיו, על גבי גיטרה רכה וקצב עדין.'),
('Oh Lord Give Us More Money', 'קטע ארוך ורחב, עם תפילה מבודחת לעוד כסף.'),
])

add(432, [
'''הפוליס, שלישייה לונדונית, היו תערובת מוזרה: סטינג, מורה לשעבר ונגן ג׳אז מניוקאסל, אנדי סאמרס, גיטריסט מבוגר יותר עם עבר בלהקות של שנות השישים, וסטיוארט קופלנד, מתופף אמריקאי אנרגטי. הם השתמשו באנרגיה של הפאנק, אבל הוסיפו לה רגאיי וג׳אז. Reggatta de Blanc, אלבומם השני, יצא ב־1979, ושמו הוא צרפתית מומצאת ל"רגאיי לבן".''',
'''הצליל של הפוליס מלא אוויר: הבס של סטינג משאיר חללים, הגיטרה של סאמרס מנגנת אקורדים עשירים עם הדים, והתופים של קופלנד קופצים ומפתיעים, עם מכות קצרות ומדויקות. Message in a Bottle, הפותח, מספר על אדם בודד על אי ששולח מכתב בבקבוק, ומגלה בסוף שמיליוני בקבוקים נוספים מחכים על החוף. Walking on the Moon איטי ורחב, עם בס שקופץ כמו צעדים על הירח, ו־The Bed's Too Big Without You הוא רגאיי עצוב על מיטה ריקה אחרי פרידה. יש גם שיר הנושא, קטע אינסטרומנטלי שנבנה מאלתור בהופעות, ו־On Any Other Day, שבו קופלנד שר על יום רע במיוחד.''',
'''האלבום הגיע למקום הראשון באנגליה, ו־Message in a Bottle ו־Walking on the Moon הגיעו שניהם לראש מצעד הסינגלים. הפוליס הפכו בזכותו לאחת הלהקות הגדולות באנגליה, ובתוך כמה שנים לאחת הגדולות בעולם.''',
'''שמעו את Walking on the Moon באוזניות, והקשיבו לחללים בין הצלילים: חלק גדול מהקסם של הפוליס הוא במה שהם לא מנגנים.''',
], [
('Message in a Bottle', 'אדם בודד שולח מכתב בבקבוק, ומגלה שהוא לא הבודד היחיד.'),
('Walking on the Moon', 'איטי ורחב, עם בס שקופץ כמו צעדים על פני הירח.'),
('The Bed\'s Too Big Without You', 'רגאיי עצוב ומהורהר על מיטה ריקה מדי אחרי פרידה.'),
])

add(433, [
'''הפול, ממנצ׳סטר, היו במשך ארבעים שנה הלהקה של אדם אחד: מארק אי. סמית׳, זמר וכותב עקשן, חד לשון ובלתי צפוי, שהחליף נגנים שוב ושוב, אבל תמיד שמר על הצליל והגישה. Live at the Witch Trials, אלבומם הראשון, יצא ב־1979, והוקלט במהירות רבה, בתוך יום או יומיים, כמעט כמו הופעה. סמית׳ היה אז בן עשרים ואחת.''',
'''המוזיקה פשוטה וחוזרנית: גיטרה חורקת, בס עבה, קלידים זולים ותופים מונוטוניים, שחוזרים על אותו רעיון שוב ושוב, כמעט כמו מכונה. מעל זה סמית׳ לא באמת שר, אלא מדבר, צועק ולועג, בקול צפוני עם מבטא כבד, ומפזר משפטים מוזרים ומצחיקים על החיים בעיר תעשייה בריטית. Rebellious Jukebox הוא שיר מהיר על קופסת נגינה שמנגנת רק מה שהיא רוצה, Industrial Estate מתאר בלעג חיים של עבודה באזור תעשייה, ו־Frightened, הפותח, איטי ומאיים, על פחד שלא עוזב. בסוף האלבום, Music Scene נמשך כמעט שמונה דקות, עם הערות שנשמעות כמו דיווח על הזמן שנשאר עד סוף התקליט.''',
'''הפול מעולם לא היו כוכבים גדולים, אבל הם אחת הלהקות המשפיעות של הרוק הבריטי העצמאי. תקליטן הרדיו האגדי ג׳ון פיל אמר שהם הלהקה האהובה עליו, והזמין אותם להקליט אצלו פעמים רבות. סמית׳ הוציא עם הפול עשרות אלבומים, עד מותו ב־2018.''',
'''זו לא מוזיקה קלה, ואפשר לא לאהוב אותה בפעם הראשונה. שמעו את Industrial Estate, הקצר והמצחיק, ואחר כך נסו את Rebellious Jukebox. אם הקול של סמית׳ תופס אתכם, הוא לא ירפה.''',
], [
('Rebellious Jukebox', 'שיר מהיר ולועג על קופסת נגינה שמנגנת רק מה שהיא עצמה רוצה.'),
('Industrial Estate', 'תיאור קצר ומצחיק של חיי עבודה משמימים באזור תעשייה.'),
('Frightened', 'הפותח: איטי, חוזרני ומאיים, על פחד שלא עוזב.'),
])

add(434, [
'''באלבום השלישי שלהם, טוקינג הדס המשיכו לעבוד עם בריאן אינו, שהפיק כבר את More Songs About Buildings and Food (אלבום 412). הפעם הם הלכו רחוק יותר: קצבים מושפעים ממוזיקה אפריקאית, צלילים מוזרים ומילים חרדות על העיר, על טכנולוגיה ועל העולם המודרני. Fear of Music יצא ב־1979, בעטיפה שחורה ומובלטת שנראית כמו רצפת מתכת.''',
'''דייוויד בירן כותב כאן שירים על דברים פשוטים ויומיומיים, כמו אוויר, נייר, ערים וחיות, אבל כל אחד מהם הופך לסיבה לחרדה. I Zimbra, הפותח, מבוסס על שיר חסר מילים של משורר דאדא מתחילת המאה העשרים, על קצב אפריקאי מתגלגל, עם גיטרה של רוברט פריפ. Life During Wartime מתאר חיים במחתרת בעיר שנמצאת במלחמה, עם שורה מפורסמת: "זו לא מסיבה, זה לא דיסקו". Heaven, לעומת זאת, הוא בלדה שקטה ויפה שמתארת את גן העדן כמקום שבו שום דבר לא קורה אף פעם. Cities הוא שיר מהיר על חיפוש עיר מתאימה לגור בה, ו־Drugs, הסיום, נשמע כמו חלום מוזר ומטושטש. הבס של טינה וימות׳ובה והתופים של כריס פרנץ נותנים לכל זה קצב שקשה לעמוד בפניו.''',
'''האלבום נחשב לאחד השיאים של הלהקה, והוא פתח את הדרך ל־Remain in Light, האלבום הבא, שבו הרעיונות האפריקאיים הגיעו עד הסוף. רבים רואים בו תמונה מדויקת של החרדה של סוף שנות השבעים.''',
'''שמעו את I Zimbra ואת Life During Wartime ברצף, ושימו לב איך הקצב הופך לחשוב יותר מהמנגינה. אחר כך השוו ל־Talking Heads: 77 (אלבום 381), וראו כמה הלהקה השתנתה בשנתיים.''',
], [
('I Zimbra', 'שיר דאדא חסר מילים על קצב אפריקאי מתגלגל, עם גיטרה של רוברט פריפ.'),
('Life During Wartime', 'חיים במחתרת בעיר במלחמה: "זו לא מסיבה, זה לא דיסקו".'),
('Heaven', 'בלדה שקטה ויפה על גן עדן שבו שום דבר לא קורה אף פעם.'),
])

add(435, [
'''ג׳וי דיוויז׳ן נולדה במנצ׳סטר אחרי שחבריה, כמו רבים אחרים, ראו הופעה של הסקס פיסטולס. היו בה הזמר איאן קרטיס, הגיטריסט ברנרד סאמנר, הבסיסט פיטר הוק והמתופף סטיבן מוריס. Unknown Pleasures, אלבומם הראשון, יצא ב־1979 בחברת התקליטים הקטנה פקטורי, בהפקת מרטין האנט.''',
'''זו מוזיקה קרה, אפלה ומרחבית. הבס של הוק מנגן מנגינות גבוהות, כמעט כמו גיטרה, הגיטרה של סאמנר חדה ומרוחקת, והתופים של מוריס מדויקים ויבשים. האנט הוסיף הדים, רווחים וצלילים מוזרים, שיצרו תחושה של חדר ריק וגדול. מעל הכול, קרטיס שר בקול עמוק ושקט, על בדידות, על אובדן שליטה ועל ניכור. Disorder, הפותח, מהיר ונואש, She's Lost Control מבוסס על אישה שקרטיס פגש בעבודתו, שאיבדה שליטה על גופה בהתקפי מחלה, ו־Shadowplay הוא אחד השירים החזקים של הלהקה, עם גיטרה שחותכת כמו סכין. העטיפה, קווים לבנים על רקע שחור, מציגה אותות רדיו מכוכב רחוק, והפכה לאחת התמונות המוכרות בתולדות המוזיקה.''',
'''איאן קרטיס מת בגיל עשרים ושלוש, במאי 1980, כמה חודשים אחרי צאת האלבום, ושאר חברי הלהקה המשיכו תחת השם ניו אורדר. Unknown Pleasures נחשב לאחד מאלבומי הפוסט־פאנק החשובים ביותר, והשפיע על אינספור להקות של רוק אפל ועצוב, מאז ועד היום.''',
'''שמעו אותו בחושך, באוזניות, מההתחלה ועד הסוף, ותנו להדים של האנט למלא את החדר. התחילו ב־Disorder, ושימו לב לבס של הוק: הוא זה שמוביל את המנגינות.''',
], [
('Disorder', 'הפותח: מהיר ונואש, עם בס מלודי שמוביל את השיר.'),
('She\'s Lost Control', 'קצב מכני וקר, ושיר על אישה שאיבדה שליטה על גופה.'),
('Shadowplay', 'מהחזקים של הלהקה, עם גיטרה שחותכת כמו סכין.'),
])

add(436, [
'''אחרי ההצלחה העצומה של C'est Chic (אלבום 422) והאלבום שהפיקו לסיסטר סלדג׳ (אלבום 427), נייל רוג׳רס וברנרד אדוארדס היו במרכז עולם הדיסקו. אבל ב־1979 הדיסקו כבר התחיל לעורר התנגדות בארצות הברית, והיו שהפגינו נגדו ואף שרפו תקליטים. Risqué, האלבום השלישי של שיק, יצא באותו קיץ, והוא בוגר ומהורהר יותר מקודמיו.''',
'''Good Times, הפותח, הוא לכאורה שיר שמח על מסיבות ועל ליהנות מהרגע, אבל הוא נכתב בתקופה של משבר כלכלי באמריקה, ויש בו קצת אירוניה: בואו נרקוד, כי בחוץ המצב לא טוב. הבס של אדוארדס בשיר הזה הוא אחד המפורסמים בתולדות המוזיקה, ומתחתיו הגיטרה של רוג׳רס מתקתקת בלי הפסקה. My Forbidden Lover מספר על אהבה אסורה, My Feet Keep Dancing משלב ברקע רקדני סטפס אמיתיים, שהרגליים שלהם הופכות לחלק מהקצב, ו־Will You Cry (When You Hear This Song) היא בלדה עצובה ויפה. A Warm Summer Night איטי, חם וחושני. כמו תמיד אצל שיק, הכול מדויק ונקי, אבל כאן יש גם יותר צל, ויותר רגש מתחת לברק.''',
'''Good Times הגיע למקום הראשון במצעד האמריקאי, והשפעתו הייתה עצומה. הבס שלו הונח ביסוד של Rapper's Delight, אחד משירי ההיפ־הופ הראשונים שהגיעו לרדיו, ושימש השראה לבס של Another One Bites the Dust של קווין. כך שיר דיסקו אחד עזר להוליד סגנונות חדשים לגמרי.''',
'''שמעו את Good Times, ואחר כך את Rapper's Delight של שוגרהיל גאנג. תשמעו מיד מאיפה הגיע הקצב.''',
], [
('Good Times', 'שיר מסיבות שמח עם קורטוב של אירוניה, ואחד הבסים המפורסמים בעולם.'),
('My Forbidden Lover', 'שיר ריקוד על אהבה אסורה, עם גיטרה מתקתקת וקולות מתוקים.'),
('My Feet Keep Dancing', 'רקדני סטפס אמיתיים ברקע, שהרגליים שלהם הופכות לחלק מהקצב.'),
])

add(437, [
'''האנדרטונז באו מדרי שבצפון אירלנד, בתקופה של אלימות ומתח פוליטי גדול. חמישה נערים, בהם הזמר פרגל שארקי והאחים ג׳ון ודמיאן אוניל, ניגנו רוק פשוט ושמח, ובחרו במודע לא לכתוב על המצב הפוליטי אלא על חיים של בני נוער: בנות, בית ספר, משפחה ומשעמום. אלבום הבכורה שלהם יצא ב־1979.''',
'''השירים קצרים, מהירים וקליטים מאוד: גיטרות מזמזמות, פזמונים שאפשר לשיר אחרי שמיעה אחת, והקול של שארקי, רועד, גבוה ומלא רגש. יש כאן פאנק, אבל גם אהבה גדולה לפופ של שנות השישים. Jimmy Jimmy מספר על ילד מסכן שאף אחד לא מתייחס אליו, Here Comes the Summer הוא שיר שמח ופשוט על חופש הקיץ, ו־Girls Don't Like It הוא צחוק קליל על בנים ובנות. הסינגל הראשון שלהם, Teenage Kicks, הוא אולי השיר המפורסם ביותר שלהם, ובחלק מההוצאות של האלבום הוא מופיע גם כן. אין באלבום שיר ארוך או כבד: הכול נגמר בשתיים או שלוש דקות, בחיוך.''',
'''תקליטן הרדיו ג׳ון פיל התאהב ב־Teenage Kicks, השמיע אותו פעמיים ברציפות בתוכנית שלו, ואמר שזה השיר האהוב עליו בכל הזמנים. האנדרטונז הוכיחו שפאנק יכול להיות שמח ותמים, ושגם ממקום קשה אפשר לכתוב שירים על דברים פשוטים ויפים.''',
'''זה אלבום מושלם לבוקר של יום חופש. שמעו אותו ברצף, והוסיפו לו את Teenage Kicks אם הוא לא מופיע בהוצאה שלפניכם.''',
], [
('Jimmy Jimmy', 'שיר קליט ושמח במנגינה, עצוב במילים, על ילד שאף אחד לא מתייחס אליו.'),
('Here Comes the Summer', 'שיר קצר, שמח ופשוט על חופש הקיץ שמגיע סוף סוף.'),
('Girls Don\'t Like It', 'צחוק קליל על בנים ובנות, עם פזמון שנדבק מיד.'),
])

add(438, [
'''אחרי שני אלבומים של פאנק זועם (אלבום 376), הקלאש רצו להוכיח שהם יותר מלהקת פאנק. הם התבודדו בחדר חזרות בלונדון, כתבו עשרות שירים, והקליטו אותם עם המפיק גאי סטיבנס, דמות פרועה ובלתי צפויה שהכניסה לאולפן אנרגיה של הופעה. London Calling, אלבום כפול, יצא בסוף 1979, ונמכר לבקשת הלהקה במחיר של תקליט אחד.''',
'''זה מסע בין סגנונות: רוקנרול של שנות החמישים, רגאיי, סקה, ג׳אז, פופ, סול וקצת רוקבילי, והכול עם האנרגיה והזעם של הקלאש. שיר הנושא, הפותח, הוא קריאת אזהרה מאיימת על העולם המתפרק, כמו שידור רדיו אחרון לפני אסון. Spanish Bombs מחבר בין מלחמת האזרחים בספרד לבין חופשות של תיירים בחופים שם, Lost in the Supermarket הוא שיר רך ועצוב של מיק ג׳ונס על בדידות בעולם של צרכנות, ו־Clampdown הוא המנון זועם נגד מי שמוותר על חלומותיו בשביל עבודה. הבסיסט פול סימונון כתב ושר את The Guns of Brixton, רגאיי כבד ואפל, ו־Train in Vain, שלא הופיע ברשימת השירים המקורית שעל העטיפה, הפך ללהיט הראשון שלהם באמריקה.''',
'''London Calling נחשב בעיני רבים לאלבום הטוב ביותר של הקלאש, ולאחד האלבומים החשובים ביותר ברוק. גם העטיפה, תמונה של סימונון מנפץ את הבס שלו על הבמה, עם אותיות ורודות וירוקות שמחקות את אלבום הבכורה של אלביס פרסלי, הפכה לאייקון.''',
'''זה אלבום ארוך, אז שמעו אותו בשני חלקים. התחילו בשיר הנושא, ואחר כך תנו מקום ל־Lost in the Supermarket, השקט והיפה ביותר באלבום.''',
], [
('London Calling', 'קריאת אזהרה מאיימת על עולם מתפרק, כמו שידור רדיו אחרון לפני אסון.'),
('Spanish Bombs', 'מחבר בין מלחמת האזרחים בספרד לחופשות התיירים בחופים שם, בפזמון מתגלגל.'),
('Lost in the Supermarket', 'שיר רך ועצוב על בדידות בעולם של קניות וצרכנות.'),
])

add(439, [
'''ג׳פאן, להקה לונדונית, התחילה את דרכה בגלאם רוק מאופר ורועש, ולא זכתה להצלחה רבה באנגליה, למרות שמה הפכה פופולרית דווקא ביפן. ב־1979, עם המפיק ג׳ון פאנטר, הם שינו כיוון לגמרי. Quiet Life, אלבומם השלישי, הוא אלבום אלגנטי, קר ומלוטש, שבו הזמר דייוויד סילביאן מצא את הקול העמוק והמהורהר שלו.''',
'''הצליל בנוי על סינתיסייזרים רכים של ריצ׳רד ברביירי, על הבס הלא־שגרתי של מיק קארן, בס בלי שריגים שמחליק ומתפתל כמו נחש, ועל תופים מדויקים של סטיב ג׳נסן, אחיו של סילביאן. סילביאן שר כמו כוכב קולנוע אירופי מסרט ישן: רגוע, רומנטי ומרוחק. שיר הנושא, הפותח, קצבי ואלגנטי, ונשמע כמו ריקוד בסלון של מלון יוקרה. In Vogue איטי, קר ומהפנט, ו־The Other Side of Life מסיים בעיבוד מלא כלי מיתר, דרמטי ועצוב. יש גם גרסה איטית ומהורהרת ל־All Tomorrow's Parties של הוולווט אנדרגראונד (אלבום 91), שמתאימה במפתיע לעולם של הלהקה.''',
'''Quiet Life נחשב לאחד האלבומים שסללו את הדרך ל"ניו רומנטיקס", סגנון פופ אלגנטי ואלקטרוני שכבש את בריטניה בתחילת שנות השמונים. הצלחה גדולה באנגליה הגיעה ללהקה רק כמה שנים אחר כך, וסילביאן המשיך לקריירת סולו ניסיונית, ועבד בין השאר עם הולגר צ׳וקאי (אלבום 431).''',
'''שמעו את שיר הנושא, ואחר כך השוו את All Tomorrow's Parties לגרסה של הוולווט אנדרגראונד. אותו שיר, בשני עולמות שונים.''',
], [
('Quiet Life', 'הפותח: קצבי ואלגנטי, כמו ריקוד בסלון של מלון יוקרה.'),
('All Tomorrow\'s Parties', 'גרסה איטית ומהורהרת לשיר של הוולווט אנדרגראונד.'),
('The Other Side of Life', 'הסיום: דרמטי ועצוב, בעיבוד מלא כלי מיתר.'),
])

add(440, [
'''מריאן פיית׳פול הייתה בשנות השישים זמרת פופ צעירה ויפהפייה, עם להיט בשם As Tears Go By, ובת זוגו של מיק ג׳אגר. בשנות השבעים חייה התפרקו: התמכרות, עוני ותקופות של חיים ברחוב. הקול שלה, שהיה פעם עדין וגבוה, הפך נמוך, סדוק וצרוד. ב־1979 היא חזרה עם Broken English, אחד מאלבומי הקאמבק המפתיעים ביותר בתולדות הרוק.''',
'''המוזיקה עכשווית מאוד לזמנה: סינתיסייזרים, קצבים של גל חדש ודיסקו, גיטרות חדות ובס עמוק. אבל הלב הוא הקול של פיית׳פול, שבור ועייף, שנשמע כאילו חי כבר כמה חיים. שיר הנושא, הפותח, מבוסס על מחשבות על טרור ואלימות פוליטית באירופה של אותם ימים, על קצב אלקטרוני מהפנט. The Ballad of Lucy Jordan מספר על עקרת בית בפרברים שחולמת לנסוע לפריז במכונית ספורט, ומבינה שהחלומות שלה כבר לא יתגשמו. Working Class Hero הוא גרסה קרה ומאיימת לשיר של ג׳ון לנון, ו־Why D'Ya Do It, הסיום, הוא שיר זועם על בגידה, עם מילים בוטות מאוד שלא הושמעו ברדיו.''',
'''האלבום זכה להצלחה גדולה ולשבחים, והחזיר את פיית׳פול לחיים המוזיקליים. הוא הראה שקול פגום יכול להיות חזק יותר מקול מושלם, ושזמרת מהשישים יכולה להישמע עכשווית לגמרי. פיית׳פול המשיכה לשיר, לכתוב ולשחק עוד עשרות שנים.''',
'''שמעו את The Ballad of Lucy Jordan, ושימו לב כמה הקול שלה מספר את הסיפור. אחר כך חפשו את As Tears Go By מ־1964, ושמעו כמה הקול השתנה.''',
], [
('The Ballad of Lucy Jordan', 'עקרת בית שחולמת על פריז ומבינה שהחלומות לא יתגשמו.'),
('Broken English', 'שיר הנושא: קצב אלקטרוני מהפנט ומחשבות על אלימות פוליטית באירופה.'),
('Working Class Hero', 'גרסה קרה ומאיימת לשיר של ג׳ון לנון, בקולה השבור.'),
])
